F = fractions.Fraction
def rank(M):
    M = [[F(x) for x in r] for r in M]
    r = 0
    for c in range(len(M[0])):
        p = None
        for i in range(r, len(M)):
            if M[i][c] != 0:
                p = i
                break
        if p is None:
            continue
        M[r], M[p] = M[p], M[r]
        for i in range(len(M)):
            if i != r and M[i][c] != 0:
                f = M[i][c] / M[r][c]
                M[i] = [M[i][j] - f * M[r][j] for j in range(len(M[0]))]
        r += 1
    return r
